// Get fertilizer by plant name (fuzzy match)
const getFertilizerForPlant = (plantName) => {
  if (!plantName) return null;
  const lc = plantName.toLowerCase();
  for (const [key, val] of Object.entries(FERTILIZER_DB)) {
    if (lc.includes(key.toLowerCase()) || key.toLowerCase().includes(lc)) {
      return { crop: key, ...val };
    }
  }
  // Default generic recommendation
  return {
    crop: plantName,
    primary: "17-17-17",
    alternate: "DAP",
    npk: "Balanced",
    dose: "20-20-20 kg/ha",
    timing: "Basal dose at planting; top dress at 30 days",
    shopName: "Complex 17-17-17 (Balanced NPK)",
  };
};


// ═══════════════════════════════════════════════════════════════════════════
// EMBEDDED ASSETS (base64) — zero network requests needed
// ═══════════════════════════════════════════════════════════════════════════
const LOGO_B64 = "";
const FARM_B64 = "";

// ── Prescription PDF Generator (jsPDF, browser-only, no server needed) ──────
const generatePrescriptionPDF = async (result, treatmentInfo, fertilizerRec, language, preview) => {
  if (!window.jspdf) {
    await new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
      s.onload = resolve; s.onerror = reject;
      document.head.appendChild(s);
    });
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation:"portrait", unit:"mm", format:"a4" });
  const W = 210, H = 297, M = 14, CW = W - M*2;
  let y = 0;

  // ── Mini helpers ──────────────────────────────────────────────────────────
  const fc  = (r,g,b)   => doc.setTextColor(r,g,b);
  const bg  = (r,g,b)   => doc.setFillColor(r,g,b);
  const lc  = (r,g,b)   => doc.setDrawColor(r,g,b);
  const lw  = (w)       => doc.setLineWidth(w);
  const fnt = (f,s)     => { doc.setFont("helvetica",f); doc.setFontSize(s); };

  const rr = (x,yy,w,h,r,fill,stroke,slw=0.5) => {
    if (fill)   doc.setFillColor(...fill);
    if (stroke) { doc.setDrawColor(...stroke); doc.setLineWidth(slw); }
    doc.roundedRect(x,yy,w,h,r,r, fill&&stroke?"FD": fill?"F":"S");
  };

  const dot = (x,yy,col) => {
    doc.setFillColor(...col);
    doc.circle(x+2.5, yy-1.5, 1.6, "F");
  };

  const hline = (yy,col=[34,139,34],width=0.4) => {
    lc(...col); lw(width);
    doc.line(M, yy, M+CW, yy);
  };

  const secBar = (text, yy, bgCol, tcol=[255,255,255]) => {
    rr(M, yy, CW, 11, 3, bgCol, null);
    fc(...tcol); fnt("bold",11);
    doc.text(text, M+5, yy+7.5);
    return yy+16;
  };

  const subHead = (text, yy, col) => {
    fc(...col); fnt("bold",10);
    doc.text(text, M, yy);
    return yy+4;
  };

  const listItems = (lst, yy, col) => {
    lst.forEach(item => {
      if(yy > H-26) { doc.addPage(); addBg(); yy=22; }
      dot(M+2, yy, col);
      fc(55,55,55); fnt("normal",9);
      const lines = doc.splitTextToSize(item, CW-10);
      doc.text(lines, M+8, yy);
      yy += lines.length*5+2;
    });
    return yy;
  };

  // ── Farm background on every page ─────────────────────────────────────────
  const addBg = () => {
    try { doc.addImage("data:image/jpeg;base64,"+FARM_B64,"JPEG",0,0,W,H); } catch(_){}
    doc.setFillColor(255,255,255);
    // Semi-transparent white overlay — use GState for opacity
    try {
      const gs = new doc.GState({opacity:0.76});
      doc.setGState(gs);
      doc.rect(0,0,W,H,"F");
      doc.setGState(new doc.GState({opacity:1}));
    } catch(_) {
      // Fallback if GState not supported
      doc.setFillColor(255,255,255);
      doc.rect(0,0,W,H,"F");
    }
  };

  const addFooter = (page, total) => {
    bg(20,90,20); doc.rect(0, H-18, W, 18, "F");
    bg(200,155,0); doc.rect(0, H-19.2, W, 1.2, "F");
    // Leaf dots in footer
    for(const [x,y,r] of [[8,H-9,2.5],[12,H-5,2],[6,H-4,1.8]]) {
      bg(60,160,60); doc.circle(x,y,r,"F");
    }
    fc(255,255,255); fnt("normal",8);
    doc.text("AgroGuardian  -  Smart Farming Solutions  |  Powered by AI & CNN EfficientNet", W/2, H-9, {align:"center"});
    fnt("normal",7); fc(200,240,200);
    doc.text("For support, contact your nearest Krishi Vigyan Kendra (KVK)", W/2, H-4.5, {align:"center"});
    fc(220,255,220); fnt("normal",7.5);
    doc.text("Page "+page+" of "+total, W-M, H-9, {align:"right"});
  };

  // ════════════════ PAGE 1 ════════════════════════════════════════════════════
  addBg();

  // Header bands
  bg(20,90,20);  doc.rect(0, 0, W, 7, "F");
  bg(34,139,34); doc.rect(0, 7, W, 48, "F");
  bg(200,155,0); doc.rect(0, 53, W, 1.5, "F");

  // Logo (white card behind)
  rr(M, 9, 38, 38, 3, [255,255,255], null);
  try { doc.addImage("data:image/png;base64,"+LOGO_B64,"PNG",M+1,10,36,36); }
  catch(_) { bg(200,155,0); doc.circle(M+19,28,13,"F"); fc(255,255,255); fnt("bold",10); doc.text("AG",M+13,32); }

  // App title
  fc(255,255,255); fnt("bold",24); doc.text("AgroGuardian", M+44, 27);
  fnt("normal",11); doc.text("Smart Plant Disease Prescription", M+44, 36);

  // Leaf cluster top-right
  for(const [x,y2,r,g] of [[W-16,13,6,175],[W-28,20,4.5,155],[W-20,27,3.5,195],[W-34,13,3,210]]) {
    bg(55,g,55); doc.circle(x,y2,r,"F");
  }

  // Date block
  fc(240,255,220); fnt("normal",9.5);
  doc.text("Date: "+(new Date()).toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"}), W-68, 21);
  doc.text("Time: "+(new Date()).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}), W-68, 28);
  doc.text("Lang: "+language.toUpperCase(), W-68, 35);

  // PRESCRIPTION badge
  bg(200,155,0); doc.roundedRect(W-62,40,47,10,4,4,"F");
  fc(60,30,0); fnt("bold",10); doc.text("PRESCRIPTION", W-38.5, 47, {align:"center"});

  y = 62;
  hline(y, [34,139,34], 0.8); y += 7;

  // ── Crop Details ──────────────────────────────────────────────────────────
  rr(M, y, CW, 27, 4, [235,252,235], [34,139,34], 0.6);
  bg(34,139,34); doc.rect(M, y, 2.5, 27, "F");
  fc(20,90,20); fnt("bold",10); doc.text("CROP DETAILS", M+7, y+8);
  fc(55,55,55); fnt("normal",9.5);
  doc.text("Plant:", M+7, y+15); fnt("bold",9.5); doc.text(result.plant, M+21, y+15);
  fnt("normal",9.5); doc.text("Status:", M+68, y+15); fnt("bold",9.5);
  doc.text(result.isHealthy?"Healthy":"Disease Detected", M+83, y+15);
  fnt("normal",9.5); doc.text("Confidence:", W-56, y+15); fnt("bold",9.5);
  doc.text(result.confidence?.toFixed(1)+"%", W-34, y+15);
  fnt("normal",9.5); fc(55,55,55);
  doc.text("Condition:", M+7, y+23); fnt("bold",9.5);
  doc.text(result.disease||"Healthy", M+26, y+23);
  y += 33;

  // ── Disease banner ────────────────────────────────────────────────────────
  const diseaseBg = result.isHealthy ? [220,245,220] : [255,235,215];
  const diseaseBorder = result.isHealthy ? [34,139,34] : [200,100,20];
  rr(M, y, CW, 23, 4, diseaseBg, diseaseBorder, 0.8);
  fc(...(result.isHealthy?[20,100,20]:[190,80,10])); fnt("bold",13);
  doc.text(result.isHealthy?"CROP IS HEALTHY":"DISEASE DETECTED:  "+(result.disease||"").toUpperCase(), M+5, y+10);
  fc(...(result.isHealthy?[40,120,40]:[110,60,15])); fnt("normal",9);
  doc.text(result.isHealthy
    ?"Your crop looks great! Follow preventive care below to maintain health."
    :"AI Diagnosis  -  Please show this prescription to your agronomist for confirmation.",
    M+5, y+19);
  y += 29;

  // ── Treatment ─────────────────────────────────────────────────────────────
  if(treatmentInfo) {
    y = secBar("Rx   TREATMENT RECOMMENDATIONS", y, [20,90,20]);
    if(treatmentInfo.organic?.length) {
      let yy = subHead("[ORGANIC]   Organic / Bio Solutions", y, [34,139,34]);
      hline(yy,[34,139,34]); yy+=5;
      y = listItems(treatmentInfo.organic, yy, [34,139,34]); y+=4;
    }
    if(treatmentInfo.chemical?.length) {
      if(y>235){doc.addPage();addBg();y=22;}
      let yy = subHead("[CHEMICAL]   Chemical Treatments", y, [200,100,20]);
      hline(yy,[200,100,20]); yy+=5;
      y = listItems(treatmentInfo.chemical, yy, [200,100,20]); y+=4;
    }
    if(treatmentInfo.prevention?.length) {
      if(y>235){doc.addPage();addBg();y=22;}
      let yy = subHead("[SHIELD]   Prevention Measures", y, [20,80,160]);
      hline(yy,[20,80,160]); yy+=5;
      y = listItems(treatmentInfo.prevention, yy, [20,80,160]); y+=6;
    }
  }

  // ── Fertilizer ────────────────────────────────────────────────────────────
  if(fertilizerRec) {
    if(y>215){doc.addPage();addBg();y=22;}
    y = secBar("[FERTILIZER]   FERTILIZER RECOMMENDATION   (Show at your fertilizer shop)", y, [20,80,22]);
    const half=(CW-5)/2;
    // Primary
    rr(M, y, half, 27, 4, [235,252,235], [34,139,34], 0.6);
    bg(34,139,34); doc.rect(M, y, 2.5, 27, "F");
    fc(20,90,20); fnt("bold",8); doc.text("PRIMARY FERTILIZER", M+6, y+8);
    fc(15,80,15); fnt("bold",14); doc.text(fertilizerRec.shopName, M+6, y+20);
    // Alternate
    const ax=M+half+5;
    rr(ax, y, half, 27, 4, [255,250,215], [200,155,0], 0.6);
    bg(200,155,0); doc.rect(ax, y, 2.5, 27, "F");
    fc(110,65,10); fnt("bold",8); doc.text("ALTERNATE OPTION", ax+5, y+8);
    fc(100,55,5); fnt("bold",14); doc.text(fertilizerRec.alternate, ax+5, y+20);
    y += 33;
    const frows=[["Crop Type",fertilizerRec.crop],["N-P-K Profile",fertilizerRec.npk],["Recommended Dose",fertilizerRec.dose],["Application Time",fertilizerRec.timing]];
    frows.forEach(([lbl,val])=>{
      rr(M, y, CW, 8, 1, [245,255,245], [180,225,180], 0.25);
      bg(34,139,34); doc.rect(M, y, 2.5, 8, "F");
      fc(20,90,20); fnt("bold",9); doc.text(lbl+":", M+5, y+5.5);
      fc(55,55,55); fnt("normal",9);
      const ls=doc.splitTextToSize(val,CW-55);
      doc.text(ls, M+50, y+5.5);
      y+=9.5;
    });
    y+=3;
    if(y>255){doc.addPage();addBg();y=22;}
    rr(M, y, CW, 19, 3, [255,250,215], [200,155,0], 0.7);
    bg(200,155,0); doc.rect(M, y, 2.5, 19, "F");
    fc(110,65,10); fnt("bold",9.5); doc.text("FOR SHOPKEEPER:", M+5, y+7.5);
    fc(100,55,5); fnt("normal",9);
    doc.text("Please provide "+fertilizerRec.shopName+" for "+fertilizerRec.crop+" crop. Dose: "+fertilizerRec.dose+".", M+52, y+7.5);
    fnt("normal",8.5); fc(100,60,0);
    doc.text("Application:  "+fertilizerRec.timing, M+5, y+14);
    y+=25;
  }

  // ════════════════ PAGE 2 ════════════════════════════════════════════════════
  doc.addPage(); addBg(); y=22;

  // ── Plant image ───────────────────────────────────────────────────────────
  y = secBar("ANALYZED PLANT IMAGE", y, [20,90,20]);
  if(preview) {
    try {
      // Shadow effect
      bg(180,180,180); doc.rect(M+3, y, 80, 60, "F");
      doc.addImage(preview, "JPEG", M, y-1, 80, 60);
      lc(34,139,34); lw(1.8); doc.rect(M, y-1, 80, 60, "S");
      fc(80,80,80); fnt("italic",8);
      doc.text("Analyzed image — "+result.plant+(result.disease?" showing "+result.disease+" symptoms":""), M, y+63);
      y+=72;
    } catch(_) { y+=5; }
  } else { y+=5; }

  // ── Top predictions ───────────────────────────────────────────────────────
  if(result.topPredictions?.length>1) {
    if(y>240){y=22;}
    y = secBar("AI TOP PREDICTIONS", y, [34,139,34]);
    result.topPredictions.forEach((pred,i)=>{
      const isPri=i===0;
      rr(M, y, CW, 9.5, 2, isPri?[235,252,235]:[248,248,248], isPri?[34,139,34]:[220,220,220], 0.4);
      bg(...(isPri?[34,139,34]:[180,180,180])); doc.roundedRect(M+2,y+1.2,9,7,2,2,"F");
      fc(255,255,255); fnt("bold",8); doc.text("#"+(i+1), M+6.5, y+6.5, {align:"center"});
      fc(...(isPri?[20,90,20]:[80,80,80])); fnt(isPri?"bold":"normal",9.5);
      doc.text(pred.plant+"  -  "+pred.condition, M+14, y+6.5);
      fc(...(isPri?[200,155,0]:[150,150,150])); fnt("bold",9.5);
      doc.text(pred.confidence.toFixed(1)+"%", M+CW-2, y+6.5, {align:"right"});
      y+=11;
    });
    y+=6;
  }

  // ── Disclaimer (FULL, properly sized) ────────────────────────────────────
  const discText = "This AI-generated prescription is for guidance only. Always consult a certified agronomist or agricultural extension officer before applying any chemical treatment. Dosage may vary based on local soil tests, crop variety and regional regulations. AgroGuardian is a decision-support tool and does not replace professional advice.";
  const discLines = doc.splitTextToSize(discText, CW-12);
  const discH = discLines.length*4.5+18;
  if(y+discH>H-25){doc.addPage();addBg();y=22;}
  rr(M, y, CW, discH, 3, [255,250,215], [200,155,0], 0.7);
  bg(200,155,0); doc.rect(M, y, 2.5, discH, "F");
  fc(110,65,10); fnt("bold",9.5); doc.text("DISCLAIMER", M+5, y+9);
  fnt("normal",8.5); fc(100,55,5);
  doc.text(discLines, M+5, y+16);
  y+=discH+6;

  // ── Help box ──────────────────────────────────────────────────────────────
  if(y<H-40) {
    rr(M, y, CW, 15, 3, [235,252,235], [34,139,34], 0.5);
    bg(34,139,34); doc.rect(M, y, 2.5, 15, "F");
    fc(20,90,20); fnt("bold",9); doc.text("NEED HELP?", M+5, y+6.5);
    fc(55,55,55); fnt("normal",8.5);
    doc.text("Visit your nearest Krishi Vigyan Kendra (KVK) or call Kisan Call Centre: 1800-180-1551 (Toll Free)", M+36, y+6.5);
    fnt("normal",8); fc(100,100,100);
    doc.text("National Pest Surveillance System: www.agriindia.gov.in  |  Helpline: 1551", M+5, y+12);
  }

  // Footer on all pages
  const pages=doc.getNumberOfPages();
  for(let i=1;i<=pages;i++){doc.setPage(i);addFooter(i,pages);}

  // Save
  const now=new Date();
  const fname="AgroGuardian_Prescription_"+result.plant.replace(/\s+/g,"_")+"_"+now.getFullYear()+String(now.getMonth()+1).padStart(2,"0")+String(now.getDate()).padStart(2,"0")+".pdf";
  doc.save(fname);
};

