// ── Treatment database ────────────────────────────────────────────────────
const getTreatmentRecommendations = (condition) => {
  const treatments = {
    "Apple Scab":              { organic: ["Neem oil spray every 7–10 days", "Copper fungicide at bud break", "Remove and destroy infected leaves"], chemical: ["Captan 50WP", "Mancozeb 75WP", "Myclobutanil"], prevention: ["Improve air circulation by pruning", "Avoid overhead watering", "Plant resistant varieties like Liberty or Freedom"] },
    "Black Rot":               { organic: ["Bordeaux mixture (copper + lime)", "Sulfur spray", "Prune infected canes/branches"], chemical: ["Myclobutanil", "Propiconazole", "Thiophanate-methyl"], prevention: ["Remove mummified fruits from tree", "Sanitize pruning tools with bleach", "Maintain tree vigor with balanced fertilization"] },
    "Cedar Apple Rust":        { organic: ["Sulfur-based fungicide", "Neem oil", "Remove nearby juniper/cedar trees if possible"], chemical: ["Myclobutanil", "Propiconazole"], prevention: ["Plant resistant apple varieties", "Apply fungicide at pink bud stage", "Monitor nearby cedar trees for rust galls"] },
    "Powdery Mildew":          { organic: ["Baking soda solution (1 tbsp/gallon)", "Milk spray (40% milk, 60% water)", "Neem oil"], chemical: ["Sulfur fungicide", "Potassium bicarbonate", "Trifloxystrobin"], prevention: ["Increase sunlight exposure", "Reduce humidity with proper spacing", "Avoid excess nitrogen fertilizer"] },
    "Bacterial Spot":          { organic: ["Copper-based bactericide (early morning)", "Remove infected plant material", "Crop rotation (minimum 2 years)"], chemical: ["Streptomycin sulfate (where approved)", "Copper hydroxide", "Oxytetracycline"], prevention: ["Use certified disease-free seeds/transplants", "Avoid overhead irrigation", "Disinfect all tools between plants"] },
    "Early Blight":            { organic: ["Copper fungicide", "Neem oil spray", "Mulching to prevent soil splash"], chemical: ["Chlorothalonil", "Mancozeb", "Azoxystrobin"], prevention: ["Crop rotation every 2–3 years", "Remove plant debris after harvest", "Adequate plant spacing for airflow"] },
    "Late Blight":             { organic: ["Copper spray at very early stages", "Remove and bag infected plants immediately — do NOT compost"], chemical: ["Metalaxyl + Mancozeb", "Chlorothalonil", "Dimethomorph"], prevention: ["Use resistant varieties (e.g., Sarpo Mira for potato)", "Avoid wet foliage — drip irrigation preferred", "Scout regularly especially in wet/cool weather"] },
    "Common Rust":             { organic: ["Sulfur dust or spray", "Remove heavily affected leaves", "Neem oil"], chemical: ["Propiconazole", "Azoxystrobin", "Tebuconazole"], prevention: ["Plant resistant hybrid varieties", "Crop rotation", "Early planting to avoid peak rust season"] },
    "Northern Leaf Blight":    { organic: ["Copper fungicide", "Remove infected debris", "Neem oil"], chemical: ["Azoxystrobin", "Propiconazole", "Pyraclostrobin"], prevention: ["Use resistant hybrids", "Crop rotation with non-host crops", "Bury or remove crop debris"] },
    "Cercospora / Gray Leaf Spot": { organic: ["Copper-based fungicide", "Improve air circulation"], chemical: ["Strobilurin fungicides", "Triazole fungicides"], prevention: ["Resistant hybrids", "Avoid continuous corn cropping", "Minimum tillage to reduce debris"] },
    "Esca (Black Measles)":    { organic: ["Pruning infected wood", "Wound sealant after pruning", "Trichoderma-based biocontrol"], chemical: ["No fully effective chemical cure — prevention is key"], prevention: ["Prune during dry weather", "Seal all pruning wounds immediately", "Remove and destroy infected vines"] },
    "Leaf Blight (Isariopsis Leaf Spot)": { organic: ["Copper fungicide", "Remove infected leaves"], chemical: ["Mancozeb", "Iprodione"], prevention: ["Improve canopy airflow", "Avoid overhead watering", "Balanced potassium nutrition"] },
    "Huanglongbing (Citrus Greening)": { organic: ["No cure — remove infected trees to prevent spread", "Psyllid control with insecticidal soap"], chemical: ["Systemic insecticides for psyllid vector control", "Imidacloprid (soil drench)"], prevention: ["Use certified disease-free budwood", "Control Asian citrus psyllid aggressively", "Inspect new plants before introduction"] },
    "Leaf Scorch":             { organic: ["Remove infected leaves", "Copper fungicide", "Adequate irrigation"], chemical: ["Captan", "Mancozeb"], prevention: ["Avoid drought stress", "Proper fertilization", "Mulching to retain soil moisture"] },
    "Septoria Leaf Spot":      { organic: ["Copper fungicide", "Neem oil", "Remove lower infected leaves"], chemical: ["Chlorothalonil", "Mancozeb", "Azoxystrobin"], prevention: ["Crop rotation", "Avoid working in wet fields", "Mulch to reduce soil splash"] },
    "Spider Mites (Two-spotted)": { organic: ["Neem oil spray", "Insecticidal soap", "Introduce predatory mites (Phytoseiidae)"], chemical: ["Abamectin", "Bifenazate", "Spiromesifen"], prevention: ["Maintain humidity (mites prefer dry conditions)", "Regular water spray on undersides of leaves", "Avoid excessive nitrogen fertilizer"] },
    "Target Spot":             { organic: ["Copper fungicide", "Remove infected foliage"], chemical: ["Azoxystrobin", "Pyraclostrobin", "Fluxapyroxad"], prevention: ["Improve air circulation", "Crop rotation", "Avoid overhead irrigation"] },
    "Yellow Leaf Curl Virus":  { organic: ["Remove and destroy infected plants", "Reflective mulches to deter whiteflies", "Neem oil for whitefly control"], chemical: ["Imidacloprid for whitefly vector", "Thiamethoxam"], prevention: ["Use TYLCV-resistant tomato varieties", "Install insect-proof nets in nurseries", "Control whitefly populations aggressively"] },
    "Mosaic Virus":            { organic: ["Remove infected plants immediately", "Mineral oil spray to reduce aphid transmission", "Control aphid vectors"], chemical: ["No direct cure — control aphid/whitefly vectors", "Imidacloprid for vector control"], prevention: ["Use virus-resistant varieties", "Wash hands/tools before handling plants", "Control weed hosts"] },
    "Leaf Mold":               { organic: ["Improve ventilation in greenhouse", "Neem oil", "Remove infected leaves"], chemical: ["Chlorothalonil", "Mancozeb", "Iprodione"], prevention: ["Keep humidity below 85%", "Prune for airflow", "Use resistant varieties"] },
    "Healthy":                 { organic: ["Continue regular balanced fertilization", "Consistent watering schedule", "Organic mulching"], chemical: [], prevention: ["Weekly scouting for early pest/disease signs", "Maintain soil health with compost", "Rotate crops each season"] },
  };
  for (let key in treatments) {
    if (condition && condition.toLowerCase().includes(key.toLowerCase())) return treatments[key];
  }
  return treatments["Healthy"];
};

// ═══════════════════════════════════════════════════════════════════════════
function Disease() {
  const [image, setImage]               = useState(null);
  const [preview, setPreview]           = useState(null);
  const [result, setResult]             = useState(null);
  const [loading, setLoading]           = useState(false);
  const [language, setLanguage]         = useState("en");
  const [showPolygonMap, setShowPolygonMap] = useState(false);
  const [treatmentInfo, setTreatmentInfo]   = useState(null);
  const [fertilizerRec, setFertilizerRec]   = useState(null);
  const [showCamera, setShowCamera]     = useState(false);
  const [error, setError]               = useState(null);
  const [pdfLoading, setPdfLoading]     = useState(false);
  const videoRef  = useRef(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);

  const t = translations[language];

  // ── Camera functions ──────────────────────────────────────────────────────
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      if (videoRef.current) { videoRef.current.srcObject = stream; setShowCamera(true); }
    } catch (err) {
      alert("Unable to access camera. Please upload an image instead.");
    }
  };

  const capturePhoto = () => {
    const video = videoRef.current, canvas = canvasRef.current;
    if (video && canvas) {
      canvas.width = video.videoWidth; canvas.height = video.videoHeight;
      canvas.getContext("2d").drawImage(video, 0, 0);
      canvas.toBlob((blob) => {
        const file = new File([blob], "captured_image.jpg", { type: "image/jpeg" });
        setImage(file); setPreview(URL.createObjectURL(blob));
        setResult(null); setError(null); stopCamera();
      }, "image/jpeg");
    }
  };

  const stopCamera = () => {
    const stream = videoRef.current?.srcObject;
    if (stream) stream.getTracks().forEach((t) => t.stop());
    setShowCamera(false);
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) { setImage(file); setPreview(URL.createObjectURL(file)); setResult(null); setError(null); }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith("image/")) { setImage(file); setPreview(URL.createObjectURL(file)); setResult(null); setError(null); }
  };

  const handleDragOver = (e) => e.preventDefault();

  // ── API call ──────────────────────────────────────────────────────────────
  const handleSubmit = async () => {
    if (!image) { alert("Please upload or capture an image first."); return; }
    const formData = new FormData();
    formData.append("file", image);
    try {
      setLoading(true); setResult(null); setError(null);
      const response = await axios.post(`${API_BASE}/disease/predict`, formData, { headers: { "Content-Type": "multipart/form-data" } });
      const data = response.data;
      const treatment   = getTreatmentRecommendations(data.condition);
      const fertRec     = getFertilizerForPlant(data.plant);
      setResult({ plant: data.plant, disease: data.condition, isHealthy: data.is_healthy, confidence: data.confidence, topPredictions: data.top_predictions, warning: data.warning });
      setTreatmentInfo(treatment);
      setFertilizerRec(fertRec);
    } catch (err) {
      const msg = err.response?.data?.detail || err.message;
      setError(`Prediction failed: ${msg}. Make sure the backend is running on port 8000.`);
    } finally { setLoading(false); }
  };

  const handleReset = () => {
    setImage(null); setPreview(null); setResult(null); setTreatmentInfo(null);
    setFertilizerRec(null); setError(null); setShowPolygonMap(false);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleDownloadPDF = async () => {
    setPdfLoading(true);
    try {
      await generatePrescriptionPDF(result, treatmentInfo, fertilizerRec, language, preview);
    } catch (e) {
      alert("PDF generation failed: " + e.message);
    } finally {
      setPdfLoading(false);
    }
  };

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <div className="disease-container" style={{ backgroundImage: `url(${process.env.PUBLIC_URL}/farm.jpg)` }}>
      <div className="disease-overlay"></div>

      {/* Language Selector */}
      <div className="language-selector">
        {["en", "hi", "pa", "ta"].map((lang) => (
          <button key={lang} className={language === lang ? "active" : ""} onClick={() => setLanguage(lang)}>
            {lang === "en" ? "English" : lang === "hi" ? "हिंदी" : lang === "pa" ? "ਪੰਜਾਬੀ" : "தமிழ்"}
          </button>
        ))}
      </div>

      <div className="disease-content">
        <div className="disease-header">
          <h1 className="disease-title">{t.title}</h1>
          <p className="disease-subtitle">{t.subtitle}</p>
        </div>

        <div className="disease-main">
          <div className="upload-section">

            {/* Dropzone */}
            {!showCamera && !preview && (
              <div className="dropzone" onDrop={handleDrop} onDragOver={handleDragOver}>
                <div className="dropzone-content">
                  <div className="upload-icon">
                    <img src={`${process.env.PUBLIC_URL}/IoT digital farming with drone.gif`} alt="Upload plant" className="upload-gif-icon" />
                  </div>
                  <p className="dropzone-text">{t.dragDrop}</p>
                  <p className="dropzone-or">{t.or}</p>
                  <div className="upload-buttons">
                    <label className="btn btn-upload">
                      <input ref={fileInputRef} type="file" accept="image/*" onChange={handleImageChange} style={{ display: "none" }} />
                      📁 {t.browse}
                    </label>
                    <button className="btn btn-camera" onClick={startCamera}>📷 {t.capture}</button>
                  </div>
                </div>
              </div>
            )}

            {/* Camera View */}
            {showCamera && (
              <div className="camera-view">
                <video ref={videoRef} autoPlay playsInline />
                <canvas ref={canvasRef} style={{ display: "none" }} />
                <div className="camera-controls">
                  <button className="btn btn-capture" onClick={capturePhoto}>📸 {t.takePhoto}</button>
                  <button className="btn btn-secondary" onClick={stopCamera}>Cancel</button>
                </div>
              </div>
            )}

            {/* Preview */}
            {preview && (
              <div className="preview-section">
                <img src={preview} alt="Leaf preview" className="preview-image" />
                <div className="preview-actions">
                  {!result && (
                    <>
                      <button className="btn btn-primary" onClick={handleSubmit} disabled={loading}>
                        {loading ? <><span className="spinner"></span> {t.detecting}</> : <><span>🔬</span> {t.detect}</>}
                      </button>
                      <button className="btn btn-secondary" onClick={handleReset}>{t.retake}</button>
                    </>
                  )}
                </div>
              </div>
            )}

            {error && <div className="error-banner">⚠️ {error}</div>}
          </div>

          {/* Results */}
          {result && (
            <div className="results-section">
              <div className={`result-card ${result.isHealthy ? "healthy-card" : "disease-card"}`}>

                <div className="result-header">
                  <div className="result-icon">{result.isHealthy ? "✅" : "⚠️"}</div>
                  <h2>{t.result}</h2>
                </div>

                <div className="result-body">
                  {/* Plant + Condition */}
                  <div className="crop-info">
                    <div className="crop-badge">🌿 {result.plant}</div>
                    <div className="disease-name">{result.isHealthy ? t.healthy : result.disease}</div>
                  </div>

                  {/* Confidence bar */}
                  <div className="confidence-bar">
                    <div className="confidence-label">
                      <span>{t.confidence}</span>
                      <span className="confidence-value">{result.confidence?.toFixed(1)}%</span>
                    </div>
                    <div className="progress-bar">
                      <div className="progress-fill" style={{ width: `${Math.min(result.confidence, 100)}%` }} />
                    </div>
                  </div>

                  {/* Top predictions */}
                  {result.topPredictions && result.topPredictions.length > 1 && (
                    <div className="top-predictions">
                      <h4>🔢 {t.topPredictions}</h4>
                      {result.topPredictions.map((pred, idx) => (
                        <div key={idx} className="prediction-row">
                          <span className="pred-rank">#{idx + 1}</span>
                          <span className="pred-name">{pred.plant} — {pred.condition}</span>
                          <span className="pred-conf">{pred.confidence.toFixed(1)}%</span>
                        </div>
                      ))}
                    </div>
                  )}

                  {result.warning && <div className="warning-banner">⚠️ {result.warning}</div>}

                  {/* Treatment section */}
                  {treatmentInfo && (
                    <div className="treatment-section">
                      <h3>{result.isHealthy ? "🌱 Healthy Crop Tips" : t.treatment}</h3>
                      <div className="treatment-grid">
                        <div className="treatment-card">
                          <h4>🌱 Organic Solutions</h4>
                          <ul>{treatmentInfo.organic.map((item, idx) => <li key={idx}>{item}</li>)}</ul>
                        </div>
                        {treatmentInfo.chemical.length > 0 && (
                          <div className="treatment-card">
                            <h4>🧪 Chemical Options</h4>
                            <ul>{treatmentInfo.chemical.map((item, idx) => <li key={idx}>{item}</li>)}</ul>
                          </div>
                        )}
                        <div className="treatment-card prevention-card">
                          <h4>🛡️ {t.prevention}</h4>
                          <ul>{treatmentInfo.prevention.map((item, idx) => <li key={idx}>{item}</li>)}</ul>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* ── NEW: Fertilizer Recommendation Card ── */}
                  {fertilizerRec && (
                    <div className="fertilizer-section">
                      <h3>{t.fertTitle}</h3>
                      <div className="fertilizer-card">
                        {/* Header row */}
                        <div className="fert-header-row">
                          <div className="fert-primary-box">
                            <span className="fert-tag">{t.fertPrimary}</span>
                            <span className="fert-name">{fertilizerRec.shopName}</span>
                          </div>
                          <div className="fert-alt-box">
                            <span className="fert-tag">{t.fertAlt}</span>
                            <span className="fert-alt-name">{fertilizerRec.alternate}</span>
                          </div>
                        </div>

                        {/* Details */}
                        <div className="fert-details">
                          <div className="fert-detail-row">
                            <span className="fert-label">🌱 {t.fertDose}</span>
                            <span className="fert-value">{fertilizerRec.dose}</span>
                          </div>
                          <div className="fert-detail-row">
                            <span className="fert-label">📅 {t.fertTiming}</span>
                            <span className="fert-value">{fertilizerRec.timing}</span>
                          </div>
                          <div className="fert-detail-row">
                            <span className="fert-label">📊 N-P-K Profile</span>
                            <span className="fert-value">{fertilizerRec.npk}</span>
                          </div>
                        </div>

                        {/* Shopkeeper banner */}
                        <div className="fert-shop-banner">
                          <span className="fert-shop-icon">🏪</span>
                          <div>
                            <strong>{t.fertShop}:</strong> {fertilizerRec.shopName}
                            <br /><small>Crop: {fertilizerRec.crop} | Dose: {fertilizerRec.dose}</small>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* ── NEW: PDF Download Button ── */}
                  <div className="pdf-download-section">
                    <div className="pdf-note">📄 {t.pdfNote}</div>
                    <button
                      className="btn btn-pdf"
                      onClick={handleDownloadPDF}
                      disabled={pdfLoading}
                    >
                      {pdfLoading ? <><span className="spinner spinner-dark"></span> {t.downloading}</> : t.downloadPDF}
                    </button>
                  </div>

                  {/* Action buttons */}
                  <div className="action-buttons">
                    <button className="btn btn-reset" onClick={handleReset}>🔄 {t.reset}</button>
                    <button className="btn btn-satellite" onClick={() => setShowPolygonMap(!showPolygonMap)}>
                      🛰️ {t.viewMap}
                    </button>
                  </div>
                </div>
              </div>

              {/* Satellite map */}
              {showPolygonMap && (
                <div className="satellite-section">
                  <iframe
                    src="https://home.agromonitoring.com/dashboard/polygons?appid=cb7257e0724e82c018463c5541017000"
                    title="AgroMonitoring Satellite Map"
                    className="satellite-iframe"
                  />
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Disease;
